The current implementation of `_atomic_create_bytes` writes directly to the destination path. If the process crashes or a power failure occurs mid-write, a partially written/corrupt file will be left at the destination path, which violates the atomicity and durability guarantees of the store. To make this operation truly atomic, write to a temporary file in the same directory, `fsync` it, and then use `os.link` to atomically link it to the destination path (which fails if the destination already exists) before unlinking the temporary file.

```python
def _atomic_create_bytes(path: Path, payload: bytes, *, mode: int = 0o600) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    tmp_path = path.with_name(path.name + f".{os.getpid()}.tmp")
    flags = os.O_WRONLY | os.O_CREAT | os.O_EXCL
    fd = os.open(tmp_path, flags, mode)
    try:
        view = memoryview(payload)
        while view:
            written = os.write(fd, view)
            if written <= 0:
                raise StoreError("atomic_write_failed")
            view = view[written:]
        os.fsync(fd)
    except Exception:
        try:
            tmp_path.unlink()
        except FileNotFoundError:
            pass
        raise
    finally:
        os.close(fd)
    try:
        os.link(tmp_path, path)
        tmp_path.unlink()
    except FileExistsError as error:
        try:
            tmp_path.unlink()
        except FileNotFoundError:
            pass
        raise StoreError("file_already_exists") from error
    except Exception:
        try:
            tmp_path.unlink()
        except FileNotFoundError:
            pass
        raise
